CREATE TABLE IF NOT EXISTS api_providers(provider TEXT PRIMARY KEY CHECK(provider IN('openai','anthropic')),cipher TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),monthly_requests INTEGER NOT NULL DEFAULT 1000 CHECK(monthly_requests BETWEEN 1 AND 1000),budget_micros INTEGER NOT NULL DEFAULT 25000000 CHECK(budget_micros BETWEEN 10000 AND 1000000000),revision INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO api_providers(provider) VALUES('openai'),('anthropic');
CREATE TABLE IF NOT EXISTS api_models(provider TEXT NOT NULL REFERENCES api_providers(provider),model_name TEXT NOT NULL,label TEXT NOT NULL,input_cents INTEGER NOT NULL CHECK(input_cents BETWEEN 1 AND 100000),output_cents INTEGER NOT NULL CHECK(output_cents BETWEEN 1 AND 100000),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),revision INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(provider,model_name));
CREATE TABLE IF NOT EXISTS api_budget(id INTEGER PRIMARY KEY CHECK(id=1),budget_micros INTEGER NOT NULL CHECK(budget_micros BETWEEN 10000 AND 1000000000));
INSERT OR IGNORE INTO api_budget VALUES(1,50000000);
CREATE TABLE IF NOT EXISTS api_cost(turn_id TEXT PRIMARY KEY REFERENCES turns(id),provider TEXT NOT NULL,model_name TEXT NOT NULL,month TEXT NOT NULL,cost_micros INTEGER NOT NULL CHECK(cost_micros>=0),reserved_micros INTEGER NOT NULL CHECK(reserved_micros>=0),input_cents INTEGER NOT NULL,output_cents INTEGER NOT NULL,input_tokens INTEGER,output_tokens INTEGER,status TEXT NOT NULL CHECK(status IN('reserved','reported','estimated')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS api_cost_month ON api_cost(month,provider);
